export const NUCLEAR_CUES=Object.freeze([
  Object.freeze({id:'nuclear-intro',text:'老大，天上好像会下核弹欸',lines:['老大，天上好像','会下核弹欸']}),
  Object.freeze({id:'nuclear-shelter',text:'把左边吃灰的防空洞利用起来吧！',lines:['把左边吃灰的防空洞','利用起来吧！']}),
]);
export const NUCLEAR_GUIDANCE=Object.freeze({'man-5':Object.freeze({chapter:CHAPTER_FIVE,cues:NUCLEAR_CUES,createDrawing:(index,view)=>createWrittenCueDrawing(NUCLEAR_CUES[index],index,view,NUCLEAR_LETTERS)})});
const warningStrokes=[];
for(const [row,text]of ['注意！','核弹来袭'].entries()){
  const start=(600-text.length*112)/2;
  [...text].forEach((c,i)=>{for(const points of NUCLEAR_LETTERS[c])warningStrokes.push({kind:'nuclear-warning',points:points.map(([x,y])=>({x:start+i*112+x,y:10+row*132+y}))});});
}
for(const points of radiationSketch(526,62,56))warningStrokes.push({kind:'radiation',points});
export const NUCLEAR_WARNING_DRAWING=createPencilDrawing(Object.freeze({text:'注意！核弹来袭',width:600,height:260,delay:0,writeDuration:1.05,hold:2.6,eraseDuration:.8,strokeScale:2.7,opacity:.96,colors:{light:'#ce343e',dark:'#ff625d'}}),warningStrokes);
export function nuclearWarningLayout(view){const scale=Math.min(1.6,(view.width-32)/600,view.height*.48/260);return{x:(view.width-600*scale)/2,y:Math.max(82,view.height*.21-130*scale),width:600*scale,height:260*scale,scale};}
export class NuclearWarning{
  constructor(){this.hint=new PencilHint(NUCLEAR_WARNING_DRAWING);}
  start(time,reduced=false){this.hint.start(time,reduced);}
  clear(){this.hint.stop();}
  snapshot(time,reduced=false){if(this.hint.startAt!==null){const eraseAt=this.hint.startAt+(this.hint.immediate?0:NUCLEAR_WARNING_DRAWING.duration)+NUCLEAR_WARNING_DRAWING.config.hold;if(time>=eraseAt)this.hint.erase(eraseAt,reduced);}return this.hint.snapshot(time,reduced);}
}
